<template>
  <view class="page"><view v-if="scissors.length" class="list"><view v-for="item in scissors" :key="item.sn||item.id" class="tool" @tap="open(item)"><image :src="item.card_image||item.image||'/static/navigation/sravx-mark.png'" mode="aspectFill"/><view><text>{{ item.name }}</text><text class="ui-small">{{ item.warranty.text }}</text></view><button @tap.stop="unbind(item)">解除绑定</button></view></view><view v-else-if="!loading" class="empty"><image src="/static/navigation/sravx-mark.png" mode="aspectFit"/><text class="ui-strong">暂无绑定剪刀</text><text>绑定您的 Sravx 剪刀，查看专属卡片与保修信息</text></view><view class="bottom"><button @tap="showBind=true">新增绑定</button></view><view v-if="showBind" class="mask" @tap="close"><view class="modal" @tap.stop><text class="ui-strong">绑定剪刀</text><text>请输入剪刀 SN 序列号</text><input v-model="sn" maxlength="20" placeholder="例如：以SVB、SVP、SVM开头的SN码"/><view><button @tap="close">取消</button><button class="primary" @tap="bind">{{ binding?'验证中...':'确认绑定' }}</button></view></view></view><view v-if="welcome" class="mask"><view class="welcome"><image src="/static/navigation/sravx-mark.png" mode="aspectFit"/><text class="ui-small">THE TOOLS YOU DESERVE.</text><text class="ui-strong">工具已加入你的档案</text><text>{{ welcome.name }}</text><text>专属工具信息与保修服务现已可用</text><button @tap="continueWelcome">查看工具档案</button></view></view></view>
</template>
<script>
import api from '../../common/api.js'
const warranty = (date, months) => { const start = new Date(date), count = Number(months); if (Number.isNaN(start.getTime())) return { type:'unknown', text:'保修期未知' }; if (!count || count<=0) return { type:'lifetime', text:'终身保修' }; const end = new Date(start); end.setMonth(end.getMonth()+count); const format = value => `${value.getFullYear()}年${String(value.getMonth()+1).padStart(2,'0')}月${String(value.getDate()).padStart(2,'0')}日`; return { type:end<new Date()?'expired':'valid', text:`${format(start)} - ${format(end)}` } }
export default { data() { return { scissors: [], loading:true, showBind:false, sn:'', binding:false, welcome:null } }, onLoad() { this.load() }, onShow() { if(this.loaded) this.load() }, methods: { async load() { this.loading=true; try { const rows=api.asList(await api.getMyScissors()); const rank={lifetime:0,valid:1,expired:2,unknown:3}; this.scissors=rows.map(item=>({...item,warranty:warranty(item.activation_date,item.warranty_months)})).sort((a,b)=>(rank[a.warranty.type]||3)-(rank[b.warranty.type]||3)) } catch(error) { this.scissors=[] } finally { this.loading=false; this.loaded=true } }, open(item) { if(item&&item.id) uni.navigateTo({url:`/pages/scissors-after-sale/index?bindingId=${item.id}`}) }, close() { this.showBind=false; this.sn='' }, async bind() { const sn=this.sn.trim(); if(!sn) return uni.showToast({title:'请输入 SN 码',icon:'none'}); if(sn.length<8) return uni.showToast({title:'SN 码格式不正确',icon:'none'}); if(this.scissors.some(item=>String(item.sn).toUpperCase()===sn.toUpperCase())) return uni.showToast({title:'该剪刀已绑定',icon:'none'}); this.binding=true; try { await api.bindScissors(sn); this.close(); await this.load(); const item=this.scissors.find(value=>String(value.sn||'').toUpperCase()===sn.toUpperCase()); this.welcome={name:item&&item.name||'SRAVX 专业工具',id:item&&item.id} } catch(error) { uni.showToast({title:error.message||'绑定失败',icon:'none'}) } finally { this.binding=false } }, unbind(item) { uni.showModal({content:'确定解除该剪刀绑定？',confirmColor:'#0B0D10',success:async({confirm})=>{if(!confirm)return;try{await api.unbindScissors(Number(item.id));uni.showToast({title:'已解除绑定',icon:'success'});this.load()}catch(error){uni.showToast({title:error.message||'解绑失败',icon:'none'})}}}) }, continueWelcome() { const item=this.welcome; this.welcome=null; if(item&&item.id)this.open({id:item.id}) } } }
</script>
<style>
.page{min-height:100vh;padding-bottom:80px;background:#F4F6F8}.list{padding:12px 16px}.tool{position:relative;overflow:hidden;margin-bottom:14px;border-radius:14px;background:#fff;box-shadow:0 7px 17px rgba(29,29,31,.07)}.tool image{width:100%;height:230px;background:#eee}.tool>view{padding:13px}.tool>view text,.tool .ui-small{display:block}.tool>view text{font-size:17px;font-weight:700}.tool .ui-small{margin-top:4px;color:#636366;font-size:11px}.tool>button{position:absolute;right:9px;bottom:9px;margin:0;padding:0 9px;border:1px solid #ddd;border-radius:15px;background:#fff;color:#666;font-size:10px;line-height:29px}.tool>button::after,.bottom button::after,.modal button::after,.welcome button::after{border:0}.empty{display:flex;align-items:center;flex-direction:column;padding:105px 35px;text-align:center}.empty image{width:70px;height:70px;margin-bottom:17px;border-radius:14px;box-shadow:0 3px 10px rgba(0,0,0,.08)}.empty .ui-strong{font-size:17px}.empty text{margin-top:7px;color:#636366;font-size:13px;line-height:1.5}.bottom{position:fixed;right:0;bottom:0;left:0;padding:12px 16px calc(12px + env(safe-area-inset-bottom));background:#fff;border-top:1px solid #eee}.bottom button{border-radius:22px;background:#0B0D10;color:#fff;font-size:15px;line-height:44px}.mask{position:fixed;z-index:10;inset:0;display:flex;align-items:center;justify-content:center;padding:24px;background:rgba(0,0,0,.45)}.modal,.welcome{width:100%;padding:25px 20px;border-radius:14px;background:#fff;text-align:center}.modal>.ui-strong,.modal>text{display:block}.modal>.ui-strong{font-size:18px}.modal>text{margin-top:7px;color:#636366;font-size:13px}.modal input{height:45px;margin:20px 0;padding:0 10px;border:1px solid #e5e5ea;border-radius:8px;font-family:monospace;text-align:center;font-size:13px}.modal>view{display:flex;gap:10px}.modal button{flex:1;background:#F4F6F8;font-size:14px;line-height:42px}.modal button.primary{background:#0B0D10;color:#fff}.welcome{padding:32px 20px;background:linear-gradient(145deg,#252322,#0B0D10);color:#fff}.welcome image{width:65px;height:65px;padding:8px;border-radius:50%;background:#F4F7FA}.welcome .ui-small,.welcome .ui-strong,.welcome text{display:block}.welcome .ui-small{margin-top:15px;color:#DCE2E9;font-size:10px;font-weight:700;letter-spacing:1px}.welcome .ui-strong{margin-top:9px;font-size:20px}.welcome text{margin-top:8px;color:rgba(255,255,255,.7);font-size:12px}.welcome button{margin-top:20px;border-radius:20px;background:#F4F7FA;color:#0B0D10;font-size:14px;line-height:42px}
</style>
